---
export interface Props {
	name: string;
	description: string;
	category: string;
	license: string;
	website: string;
	github?: string;
	tags: string[];
	featured?: boolean;
}

const { name, description, category, license, website, github, tags, featured = false } = Astro.props;
---

<article class={`bg-white rounded-xl border ${featured ? 'border-primary-200 shadow-lg' : 'border-secondary-200'} hover:shadow-xl transition-all duration-300 overflow-hidden group`}>
	<div class="p-6">
		<div class="flex items-start justify-between mb-4">
			<div class="flex-1">
				<div class="flex items-center space-x-2 mb-2">
